INSERT IGNORE INTO item_definitions(code,display_name,asset_type_code,stackable,metadata_json,active,version) VALUES('ITEM-PENDANT-UNBIND-TICKET','펜던트귀속해제💎(/펜던트해제)','PACKAGE_ITEM',1,JSON_OBJECT('objectType','pendant_unbind_ticket','source','legacy-main.js'),1,1);
CREATE TABLE pendant_equip_confirmations(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,player_id BIGINT UNSIGNED NOT NULL,external_identity_id BIGINT UNSIGNED NOT NULL,selected_instance_id BIGINT UNSIGNED NOT NULL,selected_version BIGINT UNSIGNED NOT NULL,previous_instance_id BIGINT UNSIGNED NULL,previous_version BIGINT UNSIGNED NULL,source_index INT UNSIGNED NOT NULL,source_event_id VARCHAR(191) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,expires_at DATETIME(3) NOT NULL,consumed_at DATETIME(3) NULL,consumed_event_id VARCHAR(191) CHARACTER SET ascii COLLATE ascii_bin NULL,cancelled_at DATETIME(3) NULL,cancelled_event_id VARCHAR(191) CHARACTER SET ascii COLLATE ascii_bin NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(id),KEY idx_pendant_equip_active(player_id,consumed_at,cancelled_at,expires_at),CONSTRAINT fk_pendant_equip_player FOREIGN KEY(player_id) REFERENCES players(id),CONSTRAINT fk_pendant_equip_identity FOREIGN KEY(external_identity_id) REFERENCES external_identities(id),CONSTRAINT fk_pendant_equip_selected FOREIGN KEY(selected_instance_id) REFERENCES inventory_instances(id),CONSTRAINT fk_pendant_equip_previous FOREIGN KEY(previous_instance_id) REFERENCES inventory_instances(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('PENDANT_EQUIP','pendant_equip','VERIFIED_USER','SHADOW',1,1),('PENDANT_UNEQUIP','pendant_unequip','VERIFIED_USER','SHADOW',1,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),version=VALUES(version);
INSERT INTO command_aliases(command_text,command_code,active) VALUES('/펜던트장착','PENDANT_EQUIP',1),('장착할래','PENDANT_EQUIP',1),('생각해볼게','PENDANT_EQUIP',1),('/펜던트해제','PENDANT_UNEQUIP',1) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=1;
COMMIT;
